183	    I: Iterator<Item = &'a str>,
184	{
185	    let components: Vec<String> = header
186	        .split(',')
187	        .skip(1)
188	        .map(|s| s.trim().to_string())
189	        .filter(|s| !s.is_empty())
190	        .collect();
191	    let mut out = Vec::new();
192	    let mut id_n = 0u32;
193	    for line in rows {
194	        if line.trim().is_empty() {
195	            continue;
196	        }
197	        let mut rdr = csv::ReaderBuilder::new()
198	            .has_headers(false)
199	            .from_reader(line.as_bytes());
200	        let rec = rdr.records().next().transpose()?.unwrap_or_default();
201	        let force_id = rec.get(0).unwrap_or("").trim().to_string();
202	        if force_id.is_empty() {
203	            continue;
204	        }
205	        for (i, component_id) in components.iter().enumerate() {
206	            let cell = rec.get(i + 1).unwrap_or("").trim();
207	            if cell.is_empty() {
208	                continue;
209	            }
210	            id_n += 1;
211	            let (status, notes) = parse_residue_cell(cell);
212	            out.push(Residue {
213	                id: format!("R-{id_n:02}"),
214	                force_id: force_id.clone(),
215	                component_id: component_id.clone(),
216	                status,
217	                notes,
218	            });
219	        }
220	    }
221	    Ok(out)
222	}
