49	/// Per-parent `-a` tokens from `__fish_seen_subcommand_from PARENT` lines,
50	/// excluding lines that define `--long` flag completions (`-l`).
51	fn completion_subcommands(completions: &str) -> HashMap<String, HashSet<String>> {
52	    let mut map: HashMap<String, HashSet<String>> = HashMap::new();
53	    for line in completions.lines() {
54	        if !line.contains("__fish_seen_subcommand_from ") {
55	            continue;
56	        }
57	        // Skip long-flag completions (they don't name subcommands)
58	        if line.contains(" -l ") {
59	            continue;
60	        }
61	        let Some(vals) = extract_a_values(line) else {
62	            continue;
63	        };
64	        let Some(from_pos) = line.find("__fish_seen_subcommand_from ") else {
65	            continue;
66	        };
67	        let after = &line[from_pos + "__fish_seen_subcommand_from ".len()..];
68	        let parent: String = after.trim_start_matches('\'').split('\'').next().unwrap_or("").into();
69	        if parent.is_empty() {
70	            continue;
71	        }
72	        map.entry(parent).or_default().extend(vals);
73	    }
74	    map
75	}
