77	/// Subcommand names from `residual [args…] --help`, excluding `help` itself.
78	fn cli_subcommands(args: &[&str]) -> HashSet<String> {
79	    let mut all_args: Vec<&str> = args.to_vec();
80	    all_args.push("--help");
81	    let out = Command::new(bin())
82	        .args(&all_args)
83	        .output()
84	        .expect("residual --help");
85	    let text = String::from_utf8(out.stdout).unwrap();
86	    let mut in_cmds = false;
87	    let mut result = HashSet::new();
88	    for line in text.lines() {
89	        if line.trim_end() == "Commands:" {
90	            in_cmds = true;
91	            continue;
92	        }
93	        if !in_cmds {
94	            continue;
95	        }
96	        if line.starts_with("Options:") || line.starts_with("Arguments:") {
97	            break;
98	        }
99	        let trimmed = line.trim();
100	        if trimmed.is_empty() {
101	            continue;
102	        }
103	        if let Some(name) = trimmed.split_whitespace().next() {
104	            if name != "help" {
105	                result.insert(name.to_string());
106	            }
107	        }
108	    }
109	    result
110	}
