112	/// Skill names from `residual skill list` — data lines come after the `---` separator.
113	fn skill_names() -> HashSet<String> {
114	    let out = Command::new(bin())
115	        .args(["skill", "list"])
116	        .output()
117	        .expect("residual skill list");
118	    let text = String::from_utf8(out.stdout).unwrap();
119	    let mut past_separator = false;
120	    let mut names = HashSet::new();
121	    for line in text.lines() {
122	        if line.starts_with("---") {
123	            past_separator = true;
124	            continue;
125	        }
126	        if past_separator {
127	            if let Some(name) = line.split_whitespace().next() {
128	                names.insert(name.to_string());
129	            }
130	        }
131	    }
132	    names
133	}
