6	pub fn run(cfg: &Config, op: TagOp) -> Result<()> {
7	    match op {
8	        TagOp::Scan { path } => {
9	            let tags = scan_dir(&path)?;
10	
11	            // Load stressor IDs from storage
12	            let stressors = crate::storage::stressors::load(&cfg.residual_dir).unwrap_or_default();
13	            let stored_stressor_ids: HashSet<String> =
14	                stressors.iter().map(|s| s.id.clone()).collect();
15	
16	            // Collect all tagged IDs
17	            let mut tagged_residue_ids: HashSet<String> = HashSet::new();
18	            let mut tagged_stressor_ids: HashSet<String> = HashSet::new();
19	            for tag in &tags {
20	                match tag.kind {
21	                    TagKind::Residue => {
22	                        for id in &tag.ids {
23	                            tagged_residue_ids.insert(id.clone());
24	                        }
25	                    }
26	                    TagKind::Stressor => {
27	                        for id in &tag.ids {
28	                            tagged_stressor_ids.insert(id.clone());
29	                        }
30	                    }
31	                }
32	            }
33	
34	            // Dangling stressor tags: in tags but not in storage
35	            let dangling: Vec<&String> = tagged_stressor_ids
36	                .iter()
37	                .filter(|id| !stored_stressor_ids.contains(*id))
38	                .collect();
39	
40	            // Untagged stressors: in storage but not in any tag
41	            let untagged: Vec<&String> = stored_stressor_ids
42	                .iter()
43	                .filter(|id| !tagged_stressor_ids.contains(*id))
44	                .collect();
45	
46	            if dangling.is_empty() && untagged.is_empty() {
47	                println!("All tags valid and all stressors tagged.");
48	            } else {
49	                for id in &dangling {
50	                    println!("DANGLING: {} (in code but not in storage)", id);
51	                }
52	                for id in &untagged {
53	                    println!("UNTAGGED: {} (in storage but not referenced in code)", id);
54	                }
55	            }
56	        }
57	        TagOp::Report { path } => {
58	            let tags = scan_dir(&path)?;
59	            if tags.is_empty() {
60	                println!("No tags found.");
61	            } else {
62	                for tag in &tags {
63	                    let kind_str = match tag.kind {
64	                        TagKind::Residue  => "@residue",
65	                        TagKind::Stressor => "@stressor",
66	                    };
67	                    println!("{}:{} → {} {}", tag.file, tag.line, kind_str, tag.ids.join(", "));
68	                }
69	            }
70	        }
71	    }
72	    Ok(())
73	}
