75	pub struct Tag {
76	    pub file: String,
77	    pub line: usize,
78	    pub kind: TagKind,
79	    pub ids: Vec<String>,
80	}
81	
82	pub enum TagKind {
83	    Residue,
84	    Stressor,
85	}
86	
87	pub fn scan_dir(path: &str) -> Result<Vec<Tag>> {
88	    let root = std::path::Path::new(path);
89	    let mut tags = Vec::new();
90	    scan_path(root, &mut tags)?;
91	    Ok(tags)
92	}
93	
94	fn scan_path(path: &std::path::Path, tags: &mut Vec<Tag>) -> Result<()> {
95	    if path.is_dir() {
96	        for entry in std::fs::read_dir(path)? {
97	            let entry = entry?;
98	            let child = entry.path();
99	            // Skip hidden directories (e.g. .git)
100	            if let Some(name) = child.file_name().and_then(|n| n.to_str()) {
101	                if name.starts_with('.') {
102	                    continue;
103	                }
104	            }
105	            scan_path(&child, tags)?;
106	        }
107	    } else if path.is_file() {
108	        scan_file(path, tags)?;
109	    }
110	    Ok(())
111	}
112	
113	fn scan_file(path: &std::path::Path, tags: &mut Vec<Tag>) -> Result<()> {
114	    // Read as bytes first to detect binary files
115	    let bytes = match std::fs::read(path) {
116	        Ok(b) => b,
117	        Err(_) => return Ok(()), // skip unreadable files
118	    };
119	
120	    // Heuristic: skip binary files (contains null bytes)
121	    if bytes.contains(&0u8) {
122	        return Ok(());
123	    }
124	
125	    let content = match std::str::from_utf8(&bytes) {
126	        Ok(s) => s,
127	        Err(_) => return Ok(()), // skip non-UTF8
128	    };
129	
130	    let file_str = path.to_string_lossy().to_string();
131	
132	    for (line_idx, line) in content.lines().enumerate() {
133	        let line_num = line_idx + 1;
134	
135	        if let Some(ids) = extract_tag(line, "@residue:") {
136	            if !ids.is_empty() {
137	                tags.push(Tag {
138	                    file: file_str.clone(),
139	                    line: line_num,
140	                    kind: TagKind::Residue,
141	                    ids,
142	                });
143	            }
144	        }
145	
146	        if let Some(ids) = extract_tag(line, "@stressor:") {
147	            if !ids.is_empty() {
148	                tags.push(Tag {
149	                    file: file_str.clone(),
150	                    line: line_num,
151	                    kind: TagKind::Stressor,
152	                    ids,
153	                });
154	            }
155	        }
156	    }
157	
158	    Ok(())
159	}
160	
161	/// Extract IDs after a tag marker within a comment context.
162	/// Returns Some(ids) if the tag marker is found, None otherwise.
163	fn extract_tag(line: &str, marker: &str) -> Option<Vec<String>> {
164	    // Find the marker in the line (comment lines contain it anywhere)
165	    let pos = line.find(marker)?;
166	    let after = &line[pos + marker.len()..];
167	
168	    // Parse comma-separated IDs (e.g. "R-01, R-02" or "S-01")
169	    let ids: Vec<String> = after
170	        .split(',')
171	        .map(|s| s.trim().to_string())
172	        .filter(|s| !s.is_empty() && (s.starts_with("R-") || s.starts_with("S-") || s.starts_with("P-")))
173	        .collect();
174	
175	    Some(ids)
176	}
