45	/// One-way tag rule: metadata MAY exist without codebase tags;
46	/// if tagged in code, MUST exist in metadata.
47	pub fn check_one_way_tags<S, T>(metadata_ids: &[S], tagged_ids: &[T]) -> Result<()>
48	where
49	    S: AsRef<str>,
50	    T: AsRef<str>,
51	{
52	    let meta: HashSet<String> = metadata_ids
53	        .iter()
54	        .map(|s| s.as_ref().to_string())
55	        .collect();
56	    let mut missing = Vec::new();
57	    for id in tagged_ids {
58	        let id = id.as_ref();
59	        if !meta.contains(id) {
60	            missing.push(id.to_string());
61	        }
62	    }
63	    if missing.is_empty() {
64	        Ok(())
65	    } else {
66	        bail!(
67	            "tagged in code but missing from metadata: {}",
68	            missing.join(", ")
69	        )
70	    }
71	}
