74	/// (stakeholder + direct user). Personas module stores; Verification checks.
75	pub fn check_personas_adequacy<S: AsRef<str>>(names: &[S]) -> Result<()> {
76	    if names.len() < 2 {
77	        bail!(
78	            "verification requires at least 2 personas (stakeholder + direct user) until alpha/beta exist; found {}",
79	            names.len()
80	        );
81	    }
82	    Ok(())
83	}
