187	fn bootstrap_status_section(n_attractors: usize, n_stressors: usize, n_purposes: usize) -> Option<String> {
188	    let mut issues: Vec<String> = Vec::new();
189	    if n_attractors == 0 { issues.push("0 attractors".to_string()); }
190	    if n_stressors == 0  { issues.push("0 stressors".to_string()); }
191	    if n_purposes == 0   { issues.push("0 purposes".to_string()); }
192	    if n_attractors > n_stressors && n_stressors > 0 {
193	        issues.push(format!(
194	            "{n_attractors} attractor(s) but only {n_stressors} stressor(s) — stress space underexplored"
195	        ));
196	    }
197	
198	    if issues.is_empty() {
199	        return None;
200	    }
201	
202	    let mut out = String::from("## Bootstrap Required\n\n");
203	    out.push_str("Ledger is uninitialized or underspecified:\n");
204	    for issue in &issues {
205	        out.push_str(&format!("- {issue}\n"));
206	    }
207	    out.push_str(
208	        "\n**Do not begin skill analysis until the three primitives exist.**\n\n\
209	         **Attractor** — A recurring *system state*, not a mission statement. \
210	         Describe two sides of the same coin: what the system does when healthy (`positive_state`) \
211	         and what it looks like when broken (`negative_state`). \
212	         One attractor per stable behavioral mode — do not bundle multiple concerns. \
213	         If the description lists distinct goals joined by \"and\", it is probably several attractors.\n\n\
214	         **Stressors** — Forces that push the system from the positive attractor toward the negative. \
215	         Coherence matters, not likelihood. \
216	         Archaeological source: `git log --stat --oneline | head -40` reveals wide-spanning commits \
217	         (component coupling the original architecture was naive to) and recurring churn on the same files \
218	         (rework the design did not anticipate). These stressors are already in the history.\n\n\
219	         **Purposes** — Behavioral contracts that must hold for the attractor to remain stable. \
220	         Each purpose is a feature or behavior that, if absent or broken, moves the system toward its \
221	         negative attractor state.\n\n\
222	         ### Bootstrapping steps (Socratic — propose each for approval before `residual add`)\n\n\
223	         1. Ask the user to describe the core system capability. Separate the healthy state from the \
224	         broken state — that is the attractor. Do not write a mission statement.\n\
225	         2. Run `git log --stat --oneline | head -40` to surface architectural complexity signals.\n\
226	         3. Present the proposed attractor (positive + negative state) for user approval before \
227	         `residual add attractor`.\n\
228	         4. Elicit stressors from archaeological evidence and user discussion; propose each before recording.\n\
229	         5. Derive purposes from the attractor positive state; propose each before recording.\n\n",
230	    );
231	    Some(out)
232	}
