234	/// Socratic verify guidance: strict → fix with operator first; else note and proceed.
235	fn verify_status_section(cfg: &Config) -> Result<String> {
236	    let outcome_violations = crate::verify::check_outcomes(cfg).unwrap_or_default();
237	    let link_violations = crate::verify::check_links(cfg).unwrap_or_default();
238	    let total = outcome_violations.len() + link_violations.len();
239	    let strict = cfg.validation.strict;
240	
241	    let mut out = String::new();
242	    out.push_str("## Verify status\n");
243	    out.push_str(&format!(
244	        "Policy: `super_strict` / validation.strict = **{}**\n\n",
245	        strict
246	    ));
247	
248	    if total == 0 {
249	        out.push_str("Ledger checks passed. Proceed Socratically with the skill.\n\n");
250	        return Ok(out);
251	    }
252	
253	    out.push_str(&format!(
254	        "**{total}** verify finding(s) ({} outcome, {} link):\n",
255	        outcome_violations.len(),
256	        link_violations.len()
257	    ));
258	    for v in outcome_violations.iter().take(8) {
259	        out.push_str(&format!(
260	            "- outcome [{}] {}: {} — {}\n",
261	            v.source, v.id, v.outcome_str, v.reason
262	        ));
263	    }
264	    for v in link_violations.iter().take(8) {
265	        out.push_str(&format!("- link [{}] {}: {}\n", v.source, v.id, v.message));
266	    }
267	    if total > 16 {
268	        out.push_str(&format!("- …and {} more (run `residual verify all`)\n", total - 16));
269	    }
270	    out.push('\n');
271	
272	    if strict {
273	        out.push_str(
274	            "**Strict mode — fix before analysis.** Work Socratically with the operator: \
275	             propose concrete `residual add` / edits that clear these findings, wait for approval, \
276	             re-run `residual verify all`, then continue the skill. Do not invent architecture on a broken baseline.\n\n",
277	        );
278	    } else {
279	        out.push_str(
280	            "**Advisory mode — note and proceed.** Surface these findings to the operator, then jump into the skill. \
281	             Repair when ready; capture is not blocked. Still Socratic: gather freely, modify only with approval.\n\n",
282	        );
283	    }
284	    Ok(out)
285	}
