}

/// True when a `//` or `#` comment marker appears before the tag on the line.
/// Excludes ledger CSV rows and prose that merely mentions the tag syntax —
/// e.g. residual/*.csv stressor descriptions discussing tagging itself.
fn preceded_by_comment_marker(prefix: &str) -> bool {
    prefix.contains("//") || prefix.contains('#')
}

