213	/// Extract shortnames after a tag marker within a comment context.
214	/// Returns Some(ids) if the tag marker is found within an actual comment, None
215	/// otherwise. Legacy numeric-ID shapes (S-01, P-03, R-02) are filtered out — the
216	/// tagging system is shortname-only (A-19: names hold up as the ledger scales,
217	/// IDs don't).
218	fn extract_tag(line: &str, marker: &str) -> Option<Vec<String>> {
219	    let pos = line.find(marker)?;
220	    if !preceded_by_comment_marker(&line[..pos]) {
221	        return None;
222	    }
223	    let after = &line[pos + marker.len()..];
224	
225	    let ids: Vec<String> = after
226	        .split(',')
227	        .map(|s| s.trim().to_string())
228	        .filter(|s| !is_id_shaped(s) && looks_like_shortname(s))
229	        .collect();
230	
231	    Some(ids)
232	}
233	
234	/// True for lowercase kebab-case shortnames: letters/digits, hyphen-separated,
235	/// no leading/trailing hyphen, no whitespace or punctuation. Real tags are
236	/// always terse shortnames — this rejects prose fragments that merely contain
237	/// the tag marker, e.g. a doc comment explaining the tag syntax itself.
238	fn looks_like_shortname(s: &str) -> bool {
239	    if s.is_empty() || s.starts_with('-') || s.ends_with('-') {
240	        return false;
241	    }
242	    s.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
243	}
244	
245	/// True when a `//` or `#` comment marker appears before the tag on the line.
246	/// Excludes ledger CSV rows and prose that merely mentions the tag syntax —
247	/// e.g. residual/*.csv stressor descriptions discussing tagging itself.
248	fn preceded_by_comment_marker(prefix: &str) -> bool {
249	    prefix.contains("//") || prefix.contains('#')
250	}
251	
252	/// True for legacy `<Letter>-<digits>` id shapes: S-01, P-12, R-03, A-07.
253	fn is_id_shaped(s: &str) -> bool {
254	    let mut chars = s.chars();
255	    let Some(first) = chars.next() else { return false };
256	    if !first.is_ascii_uppercase() {
257	        return false;
258	    }
259	    if chars.next() != Some('-') {
260	        return false;
261	    }
262	    let rest = &s[2..];
263	    !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit())
264	}
