/// Non-fatal: warn on tag-shaped comments (`@stressor:`/`@residue:`) that don't
/// resolve to a known stressor shortname or component — dangling tags are
/// suggestions gone stale, not a reason to block a commit (S-06).
fn print_tag_warnings(cfg: &Config) {
    let root = cfg.residual_dir.parent().unwrap_or_else(|| Path::new("."));
    let Ok(tags) = crate::tags::scan_dir(&root.to_string_lossy()) else { return };
    let Ok(report) = crate::tags::scan_report(cfg, &tags) else { return };
    for d in &report.dangling {
        println!(
            "WARNING: {}:{} {} '{}' does not match any known stressor, residue, or component",
            d.file, d.line, d.kind.marker(), d.id
        );
    }
}

